package engine

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"
)

// GENERATED-FILE ELISION IN THE RENDERED PACKET (DKT-4252).
//
// A review step's packet inlines its `issue.diff` input whole. A change that
// regenerated protobuf output put 845 KB of generated hunks into one packet, and
// the claim script refused it against the Workflow script cap, so the review
// chain never ran. The recorded artifact stays whole (a binary section past
// perFileDiffCap aside); the RENDER replaces each generated file's hunks with
// one stat line carrying the blob hash, so the
// reviewer sees that the file changed, by how much, and which bytes, and reads
// the hand-written hunks in full.
//
// A file is generated when its section of the diff carries a
// `Code generated ... DO NOT EDIT.` header line in its first lines, or when the
// checkout's .gitattributes marks its path `linguist-generated`.

// generatedHeader is Go's convention for generated source, the whole line:
// `// Code generated ... DO NOT EDIT.`. Unanchored, it matched any diff line
// that merely mentioned the phrase, so a hand-written file could hide behind
// one added or quoted line.
var generatedHeader = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

// generatedHeaderLines is how far into a file's diff section the header is
// looked for: it is the file's first line, so only hunk context within a few
// lines of the top can carry it.
const generatedHeaderLines = 40

// ElidedFile is one generated file the render replaced with a stat line.
type ElidedFile struct {
	Path string
	Blob string
	Adds int
	Dels int
}

// elideGeneratedDiff returns the diff with every generated file's section
// replaced by a stat line, and the files it elided. A diff with no generated
// file comes back byte-identical.
func elideGeneratedDiff(
	body string, attrGenerated func(path string) bool, oldHeader func(blob string) bool,
) (string, []ElidedFile) {
	if !strings.Contains(body, "diff --git ") {
		return body, nil
	}
	sections := splitDiffSections(body)
	var out strings.Builder
	var elided []ElidedFile
	for _, s := range sections {
		if s.path == "" || !(hasGeneratedHeader(s.text) ||
			(attrGenerated != nil && attrGenerated(s.path)) ||
			(oldHeader != nil && oldHeader(oldBlob(s.text)))) {
			out.WriteString(s.text)
			continue
		}
		f := ElidedFile{Path: s.path}
		for i, line := range strings.Split(s.text, "\n") {
			switch {
			case strings.HasPrefix(line, "index "):
				if _, after, ok := strings.Cut(line, ".."); ok {
					f.Blob, _, _ = strings.Cut(after, " ")
				}
			case strings.HasPrefix(line, "+++"), strings.HasPrefix(line, "---"), i == 0:
			case strings.HasPrefix(line, "+"):
				f.Adds++
			case strings.HasPrefix(line, "-"):
				f.Dels++
			}
		}
		elided = append(elided, f)
		fmt.Fprintf(&out, "diff --git a/%s b/%s\n", s.path, s.path)
		fmt.Fprintf(&out, "# generated file, hunks elided from this packet: %s (+%d -%d)", f.Path, f.Adds, f.Dels)
		if f.Blob != "" {
			fmt.Fprintf(&out, ", blob %s", f.Blob)
		}
		out.WriteString("\n# the full diff is the recorded issue.diff artifact\n")
		// A line starting `#` is never diff content (hunk lines start with a
		// space, `+`, `-` or `\`), so it is a trailer the diff builder appended
		// after the last in-scope file: the out-of-scope disclosure and round
		// delta headings. Dropping them with the hunks would let the hunks that
		// follow read as in-scope.
		for _, line := range strings.Split(s.text, "\n") {
			if strings.HasPrefix(line, "#") {
				out.WriteString(line + "\n")
			}
		}
	}
	return out.String(), elided
}

type diffSection struct {
	path string // "" for the preamble before the first file
	text string
}

// splitDiffSections cuts a unified diff at each `diff --git` line. Every
// section keeps its own trailing newline, so concatenating them is the input.
func splitDiffSections(body string) []diffSection {
	var sections []diffSection
	start := 0
	for i := 0; i <= len(body); {
		next := strings.Index(body[i:], "\ndiff --git ")
		if next < 0 {
			break
		}
		cut := i + next + 1
		sections = append(sections, newDiffSection(body[start:cut]))
		start, i = cut, cut+1
	}
	return append(sections, newDiffSection(body[start:]))
}

func newDiffSection(text string) diffSection {
	line, _, _ := strings.Cut(text, "\n")
	rest, ok := strings.CutPrefix(line, "diff --git ")
	if !ok {
		return diffSection{text: text}
	}
	_, b, ok := strings.Cut(rest, " b/")
	if !ok {
		return diffSection{text: text}
	}
	return diffSection{path: b, text: text}
}

// hasGeneratedHeader reports whether a file's diff section carries the
// generated header as the file's own first lines. It looks only in the first
// hunk, only when that hunk starts at line 1, and only at the file as it
// stood BEFORE the change (a context or removed line), so a writer cannot mark
// a hand-written file generated by adding the line. A file the change creates
// has no earlier state, so its added lines count.
func hasGeneratedHeader(section string) bool {
	lines := strings.Split(section, "\n")
	created := false
	for i, l := range lines {
		if strings.HasPrefix(l, "new file mode ") {
			created = true
		}
		if !strings.HasPrefix(l, "@@ ") {
			continue
		}
		fields := strings.Fields(l)
		if len(fields) < 3 {
			return false
		}
		old, added := fields[1], fields[2]
		if !(created && startsAtLineOne(added, "+")) && !startsAtLineOne(old, "-") {
			return false
		}
		body := lines[i+1:]
		if len(body) > generatedHeaderLines {
			body = body[:generatedHeaderLines]
		}
		for _, b := range body {
			if b == "" || strings.HasPrefix(b, "@@ ") {
				break
			}
			side, text := b[0], b[1:]
			if (side == ' ' || side == '-' || (created && side == '+')) &&
				generatedHeader.MatchString(text) {
				return true
			}
		}
		return false
	}
	return false
}

// gitattributesGenerated reads root/.gitattributes and reports whether a path
// is marked `linguist-generated`. A pattern with no slash matches a basename; a
// pattern with one matches the full path. Later lines win, as in git. A
// missing or unreadable file marks nothing.
func gitattributesGenerated(root string) func(string) bool {
	if root == "" {
		return nil
	}
	raw, err := os.ReadFile(filepath.Join(root, ".gitattributes"))
	if err != nil {
		return nil
	}
	type rule struct {
		pattern   string
		generated bool
	}
	var rules []rule
	for _, line := range strings.Split(string(raw), "\n") {
		fields := strings.Fields(line)
		if len(fields) < 2 || strings.HasPrefix(fields[0], "#") {
			continue
		}
		verdict, set := false, false
		for _, attr := range fields[1:] {
			switch attr {
			case "linguist-generated", "linguist-generated=true":
				verdict, set = true, true
			case "-linguist-generated", "linguist-generated=false":
				verdict, set = false, true
			}
		}
		if set {
			rules = append(rules, rule{pattern: fields[0], generated: verdict})
		}
	}
	if len(rules) == 0 {
		return nil
	}
	return func(p string) bool {
		generated := false
		for _, r := range rules {
			pattern := strings.TrimPrefix(r.pattern, "/")
			target := p
			if !strings.Contains(pattern, "/") {
				target = path.Base(p)
			}
			if ok, _ := path.Match(pattern, target); ok {
				generated = r.generated
			}
		}
		return generated
	}
}

// abridgeGeneratedDiffs returns the bundle with each `issue.diff` input's
// generated-file hunks elided (DKT-4252). The bundle itself is untouched: it
// also feeds `step context`, which keeps the full diff. A bundle with nothing
// to elide is returned as is.
func abridgeGeneratedDiffs(
	bundle *Context, attrGenerated func(string) bool, oldHeader func(string) bool,
) *Context {
	var inputs []ContextInput
	for i, in := range bundle.Inputs {
		if in.Kind != ArtifactKindIssueDiff {
			continue
		}
		body, elided := elideGeneratedDiff(in.Body, attrGenerated, oldHeader)
		if len(elided) == 0 {
			continue
		}
		if inputs == nil {
			inputs = append([]ContextInput(nil), bundle.Inputs...)
		}
		inputs[i].Body = body
	}
	if inputs == nil {
		return bundle
	}
	abridged := *bundle
	abridged.Inputs = inputs
	return &abridged
}

// startsAtLineOne reports whether a hunk range such as `-1,5`, `-1` or `+1,9`
// starts at line 1 (not 10, 11, ...).
func startsAtLineOne(rng, sign string) bool {
	rest, ok := strings.CutPrefix(rng, sign+"1")
	return ok && (rest == "" || strings.HasPrefix(rest, ","))
}

// oldBlob is the pre-change blob a modified file's `index OLD..NEW` line names,
// or "" for a created file (all-zero hash) or a section with no index line.
func oldBlob(section string) string {
	for _, line := range strings.Split(section, "\n") {
		rest, ok := strings.CutPrefix(line, "index ")
		if !ok {
			continue
		}
		old, _, ok := strings.Cut(rest, "..")
		if !ok || strings.Trim(old, "0") == "" {
			return ""
		}
		return old
	}
	return ""
}

// gitBlobHasGeneratedHeader reports whether the blob, read from root's object
// database, STARTS with the generated header. A regenerated file's diff carries
// the header only when the change touches the file's first lines, so the
// header is read from the file as it stood before the change: a writer cannot
// add it there, and an unreadable or unknown blob marks nothing.
func gitBlobHasGeneratedHeader(root string) func(string) bool {
	if root == "" {
		return nil
	}
	return func(blob string) bool {
		if blob == "" {
			return false
		}
		cmd := gitCommand("-c", "core.fsmonitor=false", "-C", root,
			"cat-file", "blob", blob)
		out, err := cmd.StdoutPipe()
		if err != nil || cmd.Start() != nil {
			return false
		}
		line, _ := bufio.NewReaderSize(io.LimitReader(out, 4096), 4096).ReadString('\n')
		_ = cmd.Process.Kill()
		_ = cmd.Wait()
		return generatedHeader.MatchString(strings.TrimRight(line, "\r\n"))
	}
}

// perFileDiffCap bounds one binary file's section of a recorded diff. The
// producers read every file as text (--text, so an attribute cannot hide
// content), which would otherwise record a genuine binary byte for byte. A
// section over the cap that holds a NUL byte (git's own test for binary) keeps
// its header, whose index line names the full blob ids, and drops the hunks. A
// text section is never capped: an oversize text diff stays whole, and a packet
// too large to load is refused rather than shown with a file missing.
const perFileDiffCap = 64 << 10

// capFileDiffs replaces each binary file section over perFileDiffCap with its header
// and a marker. A diff with no such section comes back byte-identical.
func capFileDiffs(body string) string {
	if len(body) <= perFileDiffCap {
		return body
	}
	var out strings.Builder
	for _, s := range splitDiffSections(body) {
		if len(s.text) <= perFileDiffCap || !strings.Contains(s.text, "\x00") {
			out.WriteString(s.text)
			continue
		}
		// The header ends at the first hunk; a section with none (a mode or
		// rename header cannot be this long) keeps its first bytes instead.
		header, _, hasHunks := strings.Cut(s.text, "\n@@")
		if !hasHunks || len(header) > perFileDiffCap {
			header = s.text[:perFileDiffCap]
		}
		out.WriteString(header)
		adds, dels := countHunkLines(s.text[len(header):])
		fmt.Fprintf(&out, "\n# === capped: +%d -%d, %d bytes of hunks for %s elided at the %d-byte per-file cap; "+
			"the index line above names the blobs ===\n", adds, dels, len(s.text)-len(header), s.path, perFileDiffCap)
	}
	return out.String()
}

// cappedMarker matches the line capFileDiffs leaves for a capped section; it
// carries the added and removed line counts so the diff facts survive the cap.
// A line starting `#` is never diff content, so a file cannot forge one.
var cappedMarker = regexp.MustCompile(`^# === capped: \+(\d+) -(\d+), `)

// countHunkLines counts the added and removed lines in a section's hunks.
func countHunkLines(hunks string) (adds, dels int) {
	for _, line := range strings.Split(hunks, "\n") {
		switch {
		case strings.HasPrefix(line, "+"):
			adds++
		case strings.HasPrefix(line, "-"):
			dels++
		}
	}
	return adds, dels
}
